// ── Shop data from Supabase (passed in from Fetch Shop Data HTTP node) ─────────
const shopData = $json || {};
const cfg  = shopData.config   || {};
const svcs = Array.isArray(shopData.services) ? shopData.services : [];
const brbs = Array.isArray(shopData.barbers)  ? shopData.barbers  : [];

const shop = {
  name:         cfg.name         || 'SkyWeb Barber Co',
  timezone:     cfg.timezone     || 'Europe/London',
  shopEmail:    cfg.shop_email   || 'theskyweb.uk@gmail.com',
  phone:        cfg.phone        || '',
  address:      cfg.address      || '',
  parking:      cfg.parking      || '',
  hoursText:    cfg.hours_text   || '',
  cancellation: cfg.cancellation || '',
  payment:      cfg.payment      || '',
  barbers:      brbs.map(b => b.name),
  barberEmails: Object.fromEntries(brbs.map(b => [b.name, b.email])),
  services:     svcs.map(s => [s.name, s.price]),
  serviceDurations: Object.fromEntries(svcs.map(s => [s.name.toLowerCase(), s.duration_minutes])),
  openHours: cfg.open_hours || { 1:['09:00','19:00'], 2:['09:00','19:00'], 3:['09:00','19:00'], 4:['09:00','19:00'], 5:['09:00','19:00'], 6:['09:00','17:00'], 7:null }
};

// ── Parse incoming webhook request ────────────────────────────────────────────
const webhookItem = $('Vapi Webhook - Barber Receptionist').first();
const raw0 = (webhookItem && webhookItem.json && (webhookItem.json.body ?? webhookItem.json)) || {};

let fnName = '';
let args = {};
let toolCallId = '';
const msg = raw0.message || {};
if (Array.isArray(msg.toolCalls) && msg.toolCalls.length) {
  const tc = msg.toolCalls[0] || {};
  toolCallId = tc.id || '';
  fnName = (tc.function && tc.function.name) || '';
  let a = (tc.function && tc.function.arguments) || {};
  if (typeof a === 'string') { try { a = JSON.parse(a); } catch (e) { a = {}; } }
  args = a || {};
} else if (msg.functionCall) {
  fnName = msg.functionCall.name || '';
  args = msg.functionCall.parameters || {};
}
const b = Object.assign({}, raw0, args);
const norm = v => String(v == null ? '' : v).trim();
const lower = v => norm(v).toLowerCase();
const intentRaw = lower(b.intent || b.action || fnName || '');
const topic = lower(b.topic || b.question || '');
const blob = intentRaw + ' ' + topic;

// ── Intent routing ───────────────────────────────────────────────────────────
const isLoc       = /location|address|direction|where|find you|park/.test(blob);
const isHours     = /hour|open|close|time/.test(blob);
const isHuman     = /human|staff|person|receptionist|call.?back|manager|someone|talk to/.test(intentRaw);
const isFaqPrice  = /pric|price|cost|how much|charge/.test(blob);
const isFaqServices = /service|offer|do you do/.test(blob);
const isFaqBarbers  = /barber|stylist|who.*cut/.test(blob);
const isFaqPay    = /pay|payment|card|cash/.test(blob);
const isFaqCancel = /refund|no.?show|cancellation policy/.test(blob);
const isBooking   = intentRaw === 'book_appointment'   || /book|appointment|schedule/.test(intentRaw);
const isCheckAvail= intentRaw === 'check_availability' || /availab|free slot|any slots|got space/.test(intentRaw);
const isLookup    = intentRaw === 'lookup_appointment' || /my appointment|my booking|when is my|do i have|check my booking|find my booking/.test(blob);
const isReschedule= intentRaw === 'reschedule_appointment' || /reschedul|move my|change my appointment|change my booking|different time/.test(blob);
const isCancel    = intentRaw === 'cancel_appointment' || /cancel my|cancel the|cancel that|cancel appointment|cancel booking/.test(blob);
const isWalkIn    = intentRaw === 'walk_in_today'      || /right now|as soon as possible|asap|today.*(fit|squeeze)|walk.?in|come in now|can i come in/.test(blob);

let route = 'booking_stub';
if      (isWalkIn)     { route = 'walk_in_today'; }
else if (isCancel)     { route = 'cancel_appointment'; }
else if (isReschedule) { route = 'reschedule_appointment'; }
else if (isLookup)     { route = 'lookup_appointment'; }
else if (isCheckAvail) { route = 'check_availability'; }
else if (isBooking)    { route = 'book_appointment'; }
else if (intentRaw === 'get_shop_info') { route = isLoc ? 'shop_location' : 'shop_hours'; }
else if (intentRaw === 'get_services_pricing') { route = 'faq'; }
else if (intentRaw === 'request_human' || isHuman) { route = 'request_human'; }
else if (isLoc)        { route = 'shop_location'; }
else if (isHours)      { route = 'shop_hours'; }
else if (isFaqPrice || isFaqServices || isFaqBarbers || isFaqPay || isFaqCancel || intentRaw === 'faq') { route = 'faq'; }

let faqTopic = 'general';
if      (isFaqPrice)    faqTopic = 'pricing';
else if (isFaqServices) faqTopic = 'services';
else if (isFaqBarbers)  faqTopic = 'barbers';
else if (isFaqPay)      faqTopic = 'payment';
else if (isFaqCancel)   faqTopic = 'cancellation';

// ── Field extraction ─────────────────────────────────────────────────────────
const callbackNumber  = norm(b.callback_number || b.phone || '');
const customerName    = norm(b.customer_name   || b.name  || '');
const phone           = norm(b.phone           || '');
const email           = norm(b.email           || b.customer_email || '');
const serviceTypeRaw  = lower(b.service_type   || b.service || '');
const preferredBarber = norm(b.preferred_barber || b.barber || '');
const preferredDate   = norm(b.preferred_date  || b.date   || '');
const preferredTime   = norm(b.preferred_time  || b.time   || '');
const notes           = norm(b.notes || '');
const confirmCancel   = b.confirm_cancel === true || b.confirm_cancel === 'true' || b.confirmed === true || lower(b.confirm_cancel) === 'yes';

// ── Service matching ─────────────────────────────────────────────────────────
const matchedService = shop.services.find(s => s[0].toLowerCase() === serviceTypeRaw) ||
  shop.services.find(s => serviceTypeRaw && s[0].toLowerCase().indexOf(serviceTypeRaw) >= 0);
const serviceName     = matchedService ? matchedService[0] : '';
const servicePrice    = matchedService ? matchedService[1] : '';
const serviceKey      = serviceName.toLowerCase();
const durationMinutes = shop.serviceDurations[serviceKey] || 30;

// ── Validation ───────────────────────────────────────────────────────────────
let errors = [];
if (route === 'request_human' && !callbackNumber) { errors.push('callback_number (a phone number for the shop to call back) is required'); }
if ((route === 'lookup_appointment' || route === 'reschedule_appointment' || route === 'cancel_appointment') && !phone) { errors.push('phone is required'); }
if (route === 'walk_in_today') {
  if (!serviceTypeRaw) errors.push('service_type is required');
  else if (!serviceName) errors.push('service_type was not recognised, please pick one of our listed services');
}
if (route === 'book_appointment' || route === 'check_availability' || route === 'reschedule_appointment') {
  if (route !== 'reschedule_appointment') {
    if (!serviceTypeRaw) errors.push('service_type is required');
    else if (!serviceName) errors.push('service_type was not recognised, please pick one of our listed services');
  } else if (serviceTypeRaw && !serviceName) {
    errors.push('service_type was not recognised, please pick one of our listed services');
  }
  if (!preferredDate) errors.push('preferred_date is required (YYYY-MM-DD)');
  if (!preferredTime) errors.push('preferred_time is required (HH:MM, 24-hour)');
}
if (route === 'book_appointment') {
  if (!customerName) errors.push('customer_name is required');
  if (!phone)        errors.push('phone is required');
  if (!email)        errors.push('email is required');
}

// ── Date/time calculation ────────────────────────────────────────────────────
let startISO = '';
let endISO   = '';
let dayOfWeek = 0;
let withinHours = false;
let dateLabel = '';
if (preferredDate && preferredTime && errors.length === 0) {
  const dt = DateTime.fromISO(preferredDate + 'T' + preferredTime, { zone: shop.timezone });
  if (!dt.isValid) {
    errors.push('preferred_date or preferred_time could not be understood, please use YYYY-MM-DD and HH:MM');
  } else {
    dayOfWeek = dt.weekday;
    const hoursForDay = shop.openHours[dayOfWeek];
    if (!hoursForDay) {
      withinHours = false;
    } else {
      const openDt = DateTime.fromISO(preferredDate + 'T' + hoursForDay[0], { zone: shop.timezone });
      const closeDt= DateTime.fromISO(preferredDate + 'T' + hoursForDay[1], { zone: shop.timezone });
      const endDt  = dt.plus({ minutes: durationMinutes });
      withinHours  = dt >= openDt && endDt <= closeDt;
    }
    startISO  = dt.toISO();
    endISO    = dt.plus({ minutes: durationMinutes }).toISO();
    dateLabel = dt.toFormat('cccc d LLLL');
  }
}

// ── FAQ answers ──────────────────────────────────────────────────────────────
const valid        = errors.length === 0;
const servicesList = shop.services.map(s => s[0]).join(', ');
const priceList    = shop.services.map(s => s[0] + ' ' + s[1]).join(', ');

let faqAnswer = '';
if      (faqTopic === 'pricing')      faqAnswer = 'Here are our prices: ' + priceList + '. Would you like to book?';
else if (faqTopic === 'services')     faqAnswer = 'We offer: ' + servicesList + '. Would you like to book one?';
else if (faqTopic === 'barbers')      faqAnswer = 'Our barbers are ' + shop.barbers.join(', ') + '. You can ask for any of them when you book.';
else if (faqTopic === 'payment')      faqAnswer = shop.payment;
else if (faqTopic === 'cancellation') faqAnswer = shop.cancellation;
else faqAnswer = 'We are ' + shop.name + '. We do haircuts, fades, beards and shaves. I can tell you our prices, hours or location, or take your number for a callback.';

const hoursText    = 'We are open ' + shop.hoursText + '.';
const locationText = 'We are at ' + shop.address + '. ' + shop.parking + '.';
const humanText    = callbackNumber ? ('Thanks. Someone from ' + shop.name + ' will call you back on ' + callbackNumber + ' shortly.') : 'No problem, I can arrange a callback. What is the best number to reach you on?';
const comingSoonText = 'Booking through me is being set up right now. For the moment I can give you our prices, opening hours or location, or take your number for a callback. Which would you like?';

return [{ json: {
  route, valid, errors, intent: intentRaw, faqTopic, toolCallId, callbackNumber, shop,
  hoursText, locationText, faqAnswer, humanText, comingSoonText,
  customerName, phone, email, notes, confirmCancel,
  serviceTypeRaw, serviceName, servicePrice, durationMinutes,
  preferredBarber, preferredDate, preferredTime, dayOfWeek, dateLabel,
  withinHours, startISO, endISO,
  raw: b
} }];

function emailWrap(shopObj, content) {
  const s = shopObj || {};
  const addr = s.address || '12 High Street, Manchester, M1 2AB';
  const phone = s.phone || '0161 123 4567';
  return '<!DOCTYPE html><html><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"></head>' +
    '<body style="margin:0;padding:0;background:#f0f0f0;font-family:Arial,Helvetica,sans-serif;">' +
    '<table width="100%" cellpadding="0" cellspacing="0" style="background:#f0f0f0;padding:24px 0;"><tr><td align="center">' +
    '<table cellpadding="0" cellspacing="0" style="max-width:600px;width:100%;background:#fff;border-radius:8px;overflow:hidden;box-shadow:0 2px 16px rgba(0,0,0,0.12);">' +
    '<tr><td style="background:#111;padding:24px 40px;text-align:center;">' +
    '<img src="https://theskyweb-portfolio.vercel.app/assets/skyweb-logo-network-CqQKEOUL.png" alt="SkyWeb Barbers Co" style="max-width:100px;height:auto;display:block;margin:0 auto 10px;" />' +
    '<p style="margin:0;color:#ffffff;font-size:18px;font-weight:bold;letter-spacing:1px;">SkyWeb Barbers Co</p>' +
    '</td></tr>' +
    '<tr><td style="background:#c9a96e;height:4px;line-height:4px;font-size:0;">&nbsp;</td></tr>' +
    '<tr><td style="padding:36px 40px;color:#333;font-size:15px;line-height:1.7;">' +
    content +
    '</td></tr>' +
    '<tr><td style="background:#111;padding:22px 40px;text-align:center;">' +
    '<p style="margin:0 0 6px;color:#c9a96e;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;">SkyWeb Barbers Co</p>' +
    '<p style="margin:0 0 4px;color:#888;font-size:12px;">' + addr + '</p>' +
    '<p style="margin:0;color:#888;font-size:12px;">' + phone + '</p>' +
    '</td></tr>' +
    '</table></td></tr></table></body></html>';
}
function infoRow(label, value) {
  return '<tr>' +
    '<td style="padding:9px 14px;background:#f8f8f8;color:#777;font-size:12px;font-weight:bold;text-transform:uppercase;letter-spacing:.5px;width:36%;border-bottom:1px solid #eee;">' + label + '</td>' +
    '<td style="padding:9px 14px;color:#222;font-size:14px;border-bottom:1px solid #eee;">' + value + '</td>' +
    '</tr>';
}
function infoTable(rows) {
  return '<table cellpadding="0" cellspacing="0" style="width:100%;border:1px solid #eee;border-radius:6px;overflow:hidden;margin:18px 0;">' + rows + '</table>';
}
function h2(title, sub) {
  return '<h2 style="color:#111;font-size:22px;margin:0 0 6px;font-weight:bold;">' + title + '</h2>' +
    (sub ? '<p style="color:#c9a96e;font-size:13px;font-weight:bold;margin:0 0 22px;text-transform:uppercase;letter-spacing:.5px;">' + sub + '</p>' : '<div style="margin-bottom:22px;"></div>');
}
function divider() { return '<hr style="border:none;border-top:1px solid #eee;margin:22px 0;" />'; }
function note(text) { return '<p style="color:#888;font-size:13px;margin:0;">' + text + '</p>'; }

const p = $('Normalize + Validate Request').item.json;
const events = $input.all().map(i => i.json);
const shop = p.shop;
const barbers = shop.barbers;

const startDt = DateTime.fromISO(p.startISO).setZone(shop.timezone);
const endDt = DateTime.fromISO(p.endISO).setZone(shop.timezone);

function parseBarberFromEvent(ev) {
  const desc = String(ev.description || '');
  const m = desc.match(/Barber:\s*([A-Za-z]+)/i);
  if (m) return m[1];
  const summary = String(ev.summary || '');
  const m2 = summary.match(/^([A-Za-z]+)\s*[-:]/);
  return m2 ? m2[1] : '';
}

function overlaps(evStartISO, evEndISO) {
  if (!evStartISO || !evEndISO) return false;
  const evStart = DateTime.fromISO(evStartISO);
  const evEnd = DateTime.fromISO(evEndISO);
  return startDt < evEnd && endDt > evStart;
}

const offToday = {};
barbers.forEach(b => { offToday[b] = false; });
events.forEach(ev => {
  const summary = String(ev.summary || '');
  const m = summary.match(/^DAY OFF:\s*([A-Za-z]+)/i);
  if (m) {
    const offBarber = barbers.find(b => b.toLowerCase() === m[1].toLowerCase());
    if (offBarber) offToday[offBarber] = true;
  }
});

const busyByBarber = {};
barbers.forEach(b => { busyByBarber[b] = !!offToday[b]; });
let possibleDuplicate = false;

events.forEach(ev => {
  const evStart = ev.start && ev.start.dateTime;
  const evEnd = ev.end && ev.end.dateTime;
  if (!overlaps(evStart, evEnd)) return;
  const evBarber = parseBarberFromEvent(ev);
  if (evBarber && busyByBarber.hasOwnProperty(evBarber)) {
    busyByBarber[evBarber] = true;
  } else if (!evBarber) {
    barbers.forEach(b => { busyByBarber[b] = true; });
  }
  const evCustomerPhone = String(ev.description || '').match(/Phone:\s*([0-9+ ]+)/i);
  if (p.phone && evCustomerPhone && evCustomerPhone[1].trim() === p.phone) {
    possibleDuplicate = true;
  }
});

let assignedBarber = '';
let available = false;

if (p.preferredBarber) {
  const wanted = barbers.find(b => b.toLowerCase() === p.preferredBarber.toLowerCase());
  if (wanted) {
    available = !busyByBarber[wanted];
    assignedBarber = wanted;
  } else {
    available = false;
  }
} else {
  const freeBarber = barbers.find(b => !busyByBarber[b]);
  if (freeBarber) {
    available = true;
    assignedBarber = freeBarber;
  }
}

const alternatives = [];
if (!available) {
  const stepMinutes = 15;
  const dayHours = shop.openHours[p.dayOfWeek];
  if (dayHours) {
    let cursor = DateTime.fromISO(p.preferredDate + 'T' + dayHours[0], { zone: shop.timezone });
    const closeDt = DateTime.fromISO(p.preferredDate + 'T' + dayHours[1], { zone: shop.timezone });
    while (cursor.plus({ minutes: p.durationMinutes }) <= closeDt && alternatives.length < 3) {
      const cEnd = cursor.plus({ minutes: p.durationMinutes });
      const isBusy = events.some(ev => {
        const evStart = ev.start && ev.start.dateTime;
        const evEnd = ev.end && ev.end.dateTime;
        if (!evStart || !evEnd) return false;
        const evS = DateTime.fromISO(evStart);
        const evE = DateTime.fromISO(evEnd);
        const evBarber = parseBarberFromEvent(ev);
        const blocksPreferred = p.preferredBarber ? (evBarber.toLowerCase() === p.preferredBarber.toLowerCase() || !evBarber) : true;
        return blocksPreferred && (cursor < evE && cEnd > evS);
      });
      const preferredOff = p.preferredBarber && offToday[barbers.find(b => b.toLowerCase() === p.preferredBarber.toLowerCase())];
      if (!isBusy && !preferredOff && (cursor.toISO() !== startDt.toISO())) {
        alternatives.push(cursor.toFormat('h:mm a'));
      }
      cursor = cursor.plus({ minutes: stepMinutes });
    }
  }
}

const barberEmail = shop.barberEmails && shop.barberEmails[assignedBarber] ? shop.barberEmails[assignedBarber] : '';
const timeStr = startDt.toFormat('h:mm a');

const customerEmailSubject = 'Booking Confirmed - ' + shop.name;
const customerEmailHtml = emailWrap(shop,
  h2('Booking Confirmed', 'Your appointment is all set') +
  '<p style="margin:0 0 16px;">Hi <strong>' + p.customerName + '</strong>,</p>' +
  '<p style="margin:0 0 4px;">Thank you for choosing <strong>' + shop.name + '</strong>. Here are your appointment details:</p>' +
  infoTable(
    infoRow('Service', p.serviceName + ' &nbsp;<span style="color:#c9a96e;font-size:12px;">(' + p.servicePrice + ')</span>') +
    infoRow('Barber', assignedBarber) +
    infoRow('Date', p.dateLabel) +
    infoRow('Time', timeStr)
  ) +
  '<p style="margin:0 0 6px;"><strong>Location</strong></p>' +
  '<p style="margin:0 0 4px;color:#555;">' + shop.address + '</p>' +
  '<p style="margin:0 0 20px;color:#888;font-size:13px;">' + shop.parking + '</p>' +
  divider() +
  note(shop.cancellation) +
  '<p style="margin:22px 0 0;color:#333;">See you soon,<br><strong>The ' + shop.name + ' Team</strong></p>'
);

const shopEmailSubject = 'New Booking: ' + p.customerName + ' with ' + assignedBarber;
const shopEmailHtml = emailWrap(shop,
  h2('New Booking', 'A new appointment has been made') +
  infoTable(
    infoRow('Customer', p.customerName) +
    infoRow('Phone', p.phone) +
    infoRow('Email', p.email || 'not given') +
    infoRow('Service', p.serviceName + ' (' + p.servicePrice + ')') +
    infoRow('Barber', assignedBarber) +
    infoRow('Date', p.dateLabel) +
    infoRow('Time', timeStr) +
    infoRow('Notes', p.notes || 'none')
  )
);

const barberEmailSubject = 'New Booking Assigned to You: ' + p.customerName;
const barberEmailHtml = emailWrap(shop,
  h2('New Appointment', 'You have a new booking') +
  '<p style="margin:0 0 16px;">Hi <strong>' + assignedBarber + '</strong>,</p>' +
  '<p style="margin:0 0 4px;">A new appointment has been added to your schedule:</p>' +
  infoTable(
    infoRow('Customer', p.customerName) +
    infoRow('Phone', p.phone) +
    infoRow('Service', p.serviceName + ' (' + p.servicePrice + ')') +
    infoRow('Date', p.dateLabel) +
    infoRow('Time', timeStr) +
    infoRow('Notes', p.notes || 'none')
  )
);

const eventSummary = assignedBarber + ' - ' + p.serviceName + ' - ' + p.customerName;
const eventDescription =
  'Barber: ' + assignedBarber + '\n' +
  'Service: ' + p.serviceName + '\n' +
  'Customer: ' + p.customerName + '\n' +
  'Phone: ' + p.phone + '\n' +
  'Email: ' + p.email + '\n' +
  'Notes: ' + (p.notes || 'none');

return [{ json: Object.assign({}, p, {
  assignedBarber, barberEmail, available, possibleDuplicate, alternatives,
  customerEmailSubject, customerEmailHtml,
  shopEmailSubject, shopEmailHtml,
  barberEmailSubject, barberEmailHtml,
  eventSummary, eventDescription,
  startTimeLabel: timeStr
}) }];

const p = $('Normalize + Validate Request').item.json;
const events = $input.all().map(i => i.json);
const shop = p.shop;

function parseField(desc, label) {
  const re = new RegExp(label + ':\\s*([^\\n]+)', 'i');
  const m = String(desc || '').match(re);
  return m ? m[1].trim() : '';
}

const now = DateTime.now().setZone(shop.timezone);

const matches = events
  .filter(ev => {
    const desc = String(ev.description || '');
    const phoneInEvent = parseField(desc, 'Phone');
    return phoneInEvent && p.phone && phoneInEvent.replace(/\s+/g, '') === p.phone.replace(/\s+/g, '');
  })
  .map(ev => {
    const desc = String(ev.description || '');
    const startDt = ev.start && ev.start.dateTime ? DateTime.fromISO(ev.start.dateTime).setZone(shop.timezone) : null;
    return {
      eventId: ev.id,
      barber: parseField(desc, 'Barber'),
      service: parseField(desc, 'Service'),
      customerName: parseField(desc, 'Customer'),
      startDt,
      startISO: ev.start && ev.start.dateTime,
      endISO: ev.end && ev.end.dateTime,
      dateLabel: startDt ? startDt.toFormat('cccc d LLLL') : '',
      timeLabel: startDt ? startDt.toFormat('h:mm a') : '',
      isPast: startDt ? startDt < now : false
    };
  })
  .filter(m => !m.isPast)
  .sort((a, b) => (a.startDt && b.startDt ? a.startDt - b.startDt : 0));

const found = matches.length > 0;
const next = found ? matches[0] : null;

let message = '';
if (!found) {
  message = "I couldn't find an upcoming appointment under that phone number. Would you like to book one, or try a different number?";
} else if (matches.length === 1) {
  message = 'You have a ' + next.service + ' booked with ' + next.barber + ' on ' + next.dateLabel + ' at ' + next.timeLabel + '.';
} else {
  message = 'You have ' + matches.length + ' upcoming appointments. The next one is a ' + next.service + ' with ' + next.barber + ' on ' + next.dateLabel + ' at ' + next.timeLabel + '.';
}

return [{ json: Object.assign({}, p, {
  found,
  matchCount: matches.length,
  nextBooking: next,
  allBookings: matches,
  lookupMessage: message
}) }];

const p = $('Normalize + Validate Request').item.json;
const events = $input.all().map(i => i.json);
const shop = p.shop;

function parseField(desc, label) {
  const re = new RegExp(label + ':\\s*([^\\n]+)', 'i');
  const m = String(desc || '').match(re);
  return m ? m[1].trim() : '';
}

const now = DateTime.now().setZone(shop.timezone);

const matches = events
  .filter(ev => {
    const desc = String(ev.description || '');
    const phoneInEvent = parseField(desc, 'Phone');
    return phoneInEvent && p.phone && phoneInEvent.replace(/\s+/g, '') === p.phone.replace(/\s+/g, '');
  })
  .map(ev => {
    const desc = String(ev.description || '');
    const startDt = ev.start && ev.start.dateTime ? DateTime.fromISO(ev.start.dateTime).setZone(shop.timezone) : null;
    return {
      eventId: ev.id,
      barber: parseField(desc, 'Barber'),
      service: parseField(desc, 'Service'),
      customerName: parseField(desc, 'Customer'),
      startDt,
