  const stepMinutes = 5;
  const candidateBarbers = (p.preferredBarber ? barbers.filter(b => b.toLowerCase() === p.preferredBarber.toLowerCase()) : barbers).filter(b => !offToday[b]);
  while (cursor.plus({ minutes: p.durationMinutes }) <= closeDt && !available) {
