const booking = $('Check Slot + Alternatives').first().json;
const resp = $json;

// Supabase returns [{id:'...'}] if overlap found, [] if not
// n8n with alwaysOutputData gives {} for empty array response
let hasConflict = false;
if (Array.isArray(resp)) {
  hasConflict = resp.length > 0;
} else if (resp && typeof resp === 'object' && Object.keys(resp).length > 0) {
  // non-empty: either a result row ({id:'...'}) or numeric-keyed items
  hasConflict = true;
}

return [{ json: { ...booking, hasConflict } }];
